    from PIL import Image, ImageOps
    import openpyxl

# ---------- Configuration ----------
DATASET_ROOT = Path("/app/workspace/dataset")
OUTPUT_XLSX = Path("/app/workspace/fuel_packets.xlsx")
IMAGE_EXTS = {".png", ".jpg", ".jpeg", ".tif", ".tiff", ".bmp", ".gif", ".webp"}

# Keywords to identify a fuel receipt (case‑insensitive)
FUEL_KEYWORDS = ["FUEL RECEIPT", "PUMP SALE", "TAX INVOICE"]

# Regex patterns (case‑insensitive)
TXN_REF_RE = re.compile(r"(?:Txn\s*Ref|Transaction\s*No|Ref\s*No)[:\s]*([A-Za-z0-9\-]+)", re.I)
DATE_RE = re.compile(r"(?:Sale\s*Date|(?<!Expiry\s)Date)[:\s]*([0-9]{1,4}[\/\-][0-9]{1,2}[\/\-][0-9]{2,4})", re.I)
AMOUNT_RE = re.compile(r"[$]?\s*([\d,]+\.\d{2})\b")

# Total amount keyword priority (high → low)
TOTAL_KEYWORDS = [
    ("GRAND TOTAL", 1),
    ("TOTAL AMOUNT", 2),
    ("AMOUNT PAID", 3),
    ("TOTAL", 4),
]
DISQUALIFY_WORDS = {"DISCOUNT", "CASHBACK", "SAVINGS", "LOYALTY", "TAX"}

# ------------------------------------------------------------

def is_image_file(path: Path) -> bool:
    return path.suffix.lower() in IMAGE_EXTS

def list_image_files(root: Path) -> List[Path]:
    files = []
    for dirpath, _, filenames in os.walk(root):
        for fname in filenames:
            p = Path(dirpath) / fname
            if is_image_file(p):
                files.append(p)
    return files

def ocr_image(path: Path) -> str:
    try:
        img = Image.open(path)
        # Convert to grayscale and increase contrast for better OCR
        img = ImageOps.grayscale(img)
        # Use a conservative Page Segmentation Mode (PSM 6 – assume a uniform block of text)
        text = pytesseract.image_to_string(img, config="--psm 6")
        return text
    except Exception as e:
        print(f"[OCR ERROR] {path}: {e}", file=sys.stderr)
        return ""

def contains_fuel_keyword(text: str) -> bool:
    upper = text.upper()
    return any(kw in upper for kw in FUEL_KEYWORDS)

def extract_txn_ref(lines: List[str]) -> str:
    for i, line in enumerate(lines):
        m = TXN_REF_RE.search(line)
        if m:
            return m.group(1).strip()
        # Look on the next line if this line only contains the label
        if any(lbl in line.upper() for lbl in ["TXN REF", "TRANSACTION NO", "REF NO"]):
            if i + 1 < len(lines):
                candidate = lines[i + 1].strip()
                if candidate:
                    return candidate
    return ""

def parse_date(raw: str) -> str:
    # Helper to convert a date string to YYYY-MM-DD according to the ambiguous‑rule policy
    parts = re.split(r"[\/\-]", raw)
    if len(parts) != 3:
        return ""
    # Pad year to 4 digits if needed
    y, m, d = None, None, None
    # Detect which part looks like a year (>31)
    if len(parts[0]) == 4:
        y, m, d = parts[0], parts[1], parts[2]
    elif len(parts[2]) == 4:
        # Assume DD/MM/YYYY or MM/DD/YYYY format
        p1, p2, y = parts[0], parts[1], parts[2]
        # Disambiguate day/month according to the rule: prefer DD/MM when both <=12
        if int(p1) <= 12 and int(p2) <= 12:
            # ambiguous – prefer DD/MM
            d, m = p1, p2
        else:
            # whichever is >12 must be the month
            if int(p1) > 12:
                m, d = p1, p2
            else:
                d, m = p1, p2
    else:
        # Unexpected format
        return ""
    try:
        y_i = int(y)
        m_i = int(m)
        d_i = int(d)
        return f"{y_i:04d}-{m_i:02d}-{d_i:02d}"
    except Exception:
        return ""

def extract_date(lines: List[str]) -> str:
    for i, line in enumerate(lines):
        m = DATE_RE.search(line)
        if m:
            return parse_date(m.group(1).strip())
        # Look at next line if label only
        if any(lbl in line.upper() for lbl in ["SALE DATE", "DATE"]):
            if i + 1 < len(lines):
                candidate = lines[i + 1].strip()
                return parse_date(candidate)
    return ""

def find_amount_candidates(lines: List[str]) -> List[Tuple[int, str, str]]:
    """Return list of (line_index, keyword, amount_str) candidates.
    The list is ordered as they appear in the file.
    """
    candidates = []
    for idx, line in enumerate(lines):
        upper = line.upper()
        # Skip lines containing disqualifying words
        if any(word in upper for word in DISQUALIFY_WORDS):
            continue
        for kw, _ in TOTAL_KEYWORDS:
            if kw in upper:
                # Try to extract amount from same line
                amt_match = AMOUNT_RE.search(line)
                if amt_match:
                    candidates.append((idx, kw, amt_match.group(1)))
                else:
                    # Look ahead for next non‑empty line containing a number
                    for j in range(idx + 1, len(lines)):
                        nxt = lines[j]
                        if not nxt.strip():
                            continue
                        amt_match = AMOUNT_RE.search(nxt)
                        if amt_match:
                            candidates.append((j, kw, amt_match.group(1)))
                        break
                break  # Only first matching keyword per line matters
    return candidates

def select_total_amount(candidates: List[Tuple[int, str, str]]) -> str:
    if not candidates:
        return ""
    # Group by keyword priority
    best = None
    best_priority = float("inf")
    # When same priority, pick the last occurrence (largest line index)
    for idx, kw, amt in candidates:
        # Determine priority
        prio = next((p for k, p in TOTAL_KEYWORDS if k == kw), 5)
        if prio < best_priority or (prio == best_priority and idx > best[0]):
            best = (idx, kw, amt)
            best_priority = prio
    # Normalise amount (remove commas, ensure two decimals)
    raw = best[2].replace(",", "")
    try:
        value = float(raw)
        return f"{value:.2f}"
    except Exception:
        return ""

def extract_fields(text: str) -> Dict[str, str]:
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    txn_ref = extract_txn_ref(lines)
    date = extract_date(lines)
    amount_cands = find_amount_candidates(lines)
    total_amount = select_total_amount(amount_cands)
    return {"txn_ref": txn_ref, "date": date, "total_amount": total_amount}

def main():
    image_paths = list_image_files(DATASET_ROOT)
    records = []
    for img_path in image_paths:
        rel_path = str(img_path.relative_to(DATASET_ROOT)).replace(os.sep, "/")
        batch_name = rel_path.split("/")[0] if "/" in rel_path else rel_path
        ocr_text = ocr_image(img_path)
        if not ocr_text:
            continue
        if not contains_fuel_keyword(ocr_text):
            continue
        fields = extract_fields(ocr_text)
        if not fields["txn_ref"]:
            # If we cannot locate a transaction reference, skip – it would break dedup logic
            continue
        record = {
            "batch_name": batch_name,
            "relative_path": rel_path,
            "txn_ref": fields["txn_ref"],
            "date": fields["date"],
            "total_amount": fields["total_amount"],
        }
        records.append(record)
        # Debug print – can be removed later
        print(f"[EXTRACTED] {rel_path} → {record}")

    # Sort by relative_path
    records.sort(key=lambda r: r["relative_path"])
    # Deduplicate by txn_ref (keep first occurrence)
    seen = set()
    deduped = []
    for rec in records:
        if rec["txn_ref"] in seen:
            continue
        seen.add(rec["txn_ref"])
        deduped.append(rec)

    # Write Excel workbook
    wb = openpyxl.Workbook()
    # Remove the default sheet
    default_sheet = wb.active
    wb.remove(default_sheet)
    ws = wb.create_sheet(title="transactions")
    headers = ["batch_name", "relative_path", "txn_ref", "date", "total_amount"]
    ws.append(headers)
    for rec in deduped:
        ws.append([rec[h] for h in headers])
    # Ensure parent directory exists
    OUTPUT_XLSX.parent.mkdir(parents=True, exist_ok=True)
    wb.save(OUTPUT_XLSX)
    print(f"\nFinished. {len(deduped)} records written to {OUTPUT_XLSX}")

if __name__ == "__main__":
    main()
